package main

import (
	"github.com/corentings/chess/v2"
	"strings"
	"testing"
)

func TestGeometricAttacksAgainstLibrary(t *testing.T) {
	for _, fen := range []string{
		chess.NewGame().FEN(),
		"r2qk2r/pp2bppp/2n1pn2/8/3P4/2NB1N2/PP3PPP/R1BQR1K1 w - - 0 12",
		"4k3/8/8/3p4/2B1N3/1P6/P6p/R3K2Q w - - 0 1",
	} {
		p := evalFEN(t, fen)
		var occupied uint64
		for sq := chess.A1; sq <= chess.H8; sq++ {
			if p.Board().Piece(sq) != chess.NoPiece {
				occupied |= uint64(1) << sq
			}
		}
		for sq := chess.A1; sq <= chess.H8; sq++ {
			piece := p.Board().Piece(sq)
			if piece == chess.NoPiece {
				continue
			}
			var want uint64
			for _, target := range p.Board().AttacksFrom(sq) {
				want |= uint64(1) << target
			}
			if got := pieceAttacks(piece, int(sq), occupied); got != want {
				t.Fatalf("%s on %s: %x want %x", piece, sq, got, want)
			}
		}
	}
}

func TestKingDangerPressureAndPhase(t *testing.T) {
	// Black queen h5 attacks h2, bishop d6 attacks h2 and g3 around Kg1.
	p := evalFEN(t, "k7/8/3b4/7q/8/8/5PPP/6K1 w - - 0 1")
	// The shield blocks further rays: queen h2 has weight 5, bishop h2 has 2.
	// Bishop's g3 is outside the king's immediate ring. 7 units, two attackers.
	if d := kingDanger(p, 24); d[chess.White] != 12 || d[chess.Black] != 0 {
		t.Fatalf("danger %v want white12/black0", d)
	}
	if d := kingDanger(p, 12); d[chess.White] != 6 {
		t.Fatalf("half phase danger %v", d)
	}
	if d := kingDanger(p, 0); d[chess.White] != 0 {
		t.Fatal("danger persisted at phase zero")
	}
	lone := evalFEN(t, "k7/8/8/7q/8/8/5PPP/6K1 w - - 0 1")
	if d := kingDanger(lone, 24); d[chess.White] != 3 {
		t.Fatalf("lone queen pressure %v want3", d)
	}
	queenless := evalFEN(t, "k7/8/3b4/7r/8/8/5PPP/6K1 w - - 0 1")
	if d := kingDanger(queenless, 24); d != [3]int{} {
		t.Fatal("queenless model changed")
	}
}

func TestKingDangerMirrorsAndImmutability(t *testing.T) {
	a := evalFEN(t, "k7/8/3b4/7q/8/8/5PPP/6K1 w - - 0 1")
	b := evalFEN(t, "6k1/5ppp/8/8/7Q/3B4/8/K7 b - - 0 1")
	before := a.String()
	key := a.ZobristHash()
	if staticScore(a, chess.White) != -staticScore(a, chess.Black) || staticScore(a, chess.White) != staticScore(b, chess.Black) {
		t.Fatal("color/perspective symmetry changed")
	}
	if materialScore(a, chess.White) != -900 {
		t.Fatal("material invariant changed")
	}
	_ = staticScore(a, chess.White)
	if a.String() != before || a.ZobristHash() != key {
		t.Fatal("evaluation mutated root")
	}
	if n := testing.AllocsPerRun(100, func() { _ = staticScore(a, chess.White) }); n != 0 {
		t.Fatalf("static allocations %v", n)
	}
}

func TestKingDangerCapAndBlockers(t *testing.T) {
	crowded := evalFEN(t, "k7/8/8/5qqq/5qqq/5qqq/8/6K1 w - - 0 1")
	if d := kingDanger(crowded, 24); d[chess.White] != 240 {
		t.Fatalf("danger cap %v", d)
	}
	if d := kingDanger(crowded, 12); d[chess.White] != 120 {
		t.Fatalf("tapered cap %v", d)
	}
	if d := kingDanger(crowded, 40); d[chess.White] != 240 {
		t.Fatal("promoted material exceeded phase cap")
	}
	// A blocker outside the ring removes the attack rather than granting x-ray pressure.
	clear := evalFEN(t, "k7/8/8/7q/8/8/5PPP/6K1 w - - 0 1")
	blocked := evalFEN(t, "k7/8/8/7q/8/7p/5PPP/6K1 w - - 0 1")
	if kingDanger(blocked, 24)[chess.White] >= kingDanger(clear, 24)[chess.White] {
		t.Fatal("outside-ring blocker did not stop queen pressure")
	}
}

func BenchmarkKingDangerEvaluation(b *testing.B) {
	p := chess.NewGame().Position()
	b.ReportAllocs()
	for b.Loop() {
		_ = staticScore(p, chess.White)
	}
}

func releasedKingStaticScore(position *chess.Position, perspective chess.Color) int {
	board := position.Board()
	phase := 0
	for square := chess.A1; square <= chess.H8; square++ {
		phase += phaseWeight(board.Piece(square).Type())
	}
	phase = min(24, phase)
	score := 0
	for square := chess.A1; square <= chess.H8; square++ {
		piece := board.Piece(square)
		if piece == chess.NoPiece {
			continue
		}
		file, rank := int(square)%8, int(square)/8
		if piece.Color() == chess.Black {
			rank = 7 - rank
		}
		value := pieceValues[piece.Type()] + placement(piece.Type(), file, rank, phase)
		if piece.Color() == perspective {
			score += value
		} else {
			score -= value
		}
	}
	return score
}

func TestKingDangerScoreBreakdown(t *testing.T) {
	for _, fen := range []string{chess.NewGame().FEN(), "k7/8/3b4/7q/8/8/5PPP/6K1 w - - 0 1", "4k3/8/8/8/3P4/8/8/4K3 w - - 0 1"} {
		p := evalFEN(t, fen)
		phase := 0
		for sq := chess.A1; sq <= chess.H8; sq++ {
			phase += phaseWeight(p.Board().Piece(sq).Type())
		}
		d := kingDanger(p, min(24, phase))
		for _, side := range []chess.Color{chess.White, chess.Black} {
			if staticScore(p, side)-releasedKingStaticScore(p, side) != d[side.Other()]-d[side] {
				t.Fatal("isolated term does not explain score")
			}
		}
	}
}
func BenchmarkKingDangerControls(b *testing.B) {
	for name, p := range map[string]*chess.Position{"start": chess.NewGame().Position(), "dense": evalFENForBenchmark("r1bq1rk1/pp1nbppp/2pp1n2/8/2B1P3/2NP1N2/PPP2PPP/R1BQ1RK1 w - - 0 8")} {
		b.Run(name+"/released", func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				_ = releasedKingStaticScore(p, chess.White)
			}
		})
		b.Run(name+"/candidate", func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				_ = staticScore(p, chess.White)
			}
		})
	}
}
func evalFENForBenchmark(fen string) *chess.Position {
	g, err := parsePosition(strings.Fields("fen " + fen))
	if err != nil {
		panic(err)
	}
	return g.Position()
}

